		Part.CastShadow = Part.Size.X * Part.Size.Y * Part.Size.Z > 1.5
		if P[14] == 1 then -- a region marker: invisible, no collision, queries or touches (MARKER_ACCESS below)
			Part.Transparency, Part.CanCollide, Part.CanQuery, Part.CanTouch, Part.CastShadow = 1, false, false, false, false
		end
		if type(P[15]) == "string" and P[15] ~= "" then -- "" = no attributes (export rows keep fields 14-16 together)
			for K, V in pairs(HS:JSONDecode(P[15])) do
				Part:SetAttribute(K, V)
			end
		end
		if type(P[16]) == "string" then -- "" = no tags
			for T in string.gmatch(P[16], "[^,]+") do
				T = T:match("^%s*(.-)%s*$")
				if T ~= "" then CS:AddTag(Part, T) end
			end
		end
		if P[14] == 1 then -- per-tag exceptions: only where a service needs a touch or a query
			for _, T in ipairs(CS:GetTags(Part)) do
				local E = MARKER_ACCESS[T]
				if E and E.CanQuery then Part.CanQuery = true end
				if E and E.CanTouch then Part.CanTouch = true end
			end
		end
		if Part:GetAttribute("Emit") == "Steam" then Steam(Part) end -- the locomotive's chimney
		Part.Parent = Model
		table.insert(List, Part)
		Parts += 1
	end
	-- lights live directly in the nearest part (LightService tags parts holding a PointLight as lamps)
	for _, L in ipairs(PF.l) do
		local At = Base * Vector3.new(L[1], L[2], L[3])
		local Best, D = nil, math.huge
		for _, Part in ipairs(List) do
			local d = (Part.Position - At).Magnitude
			if Part.Material == Enum.Material.Neon then d -= 1000 end
			if d < D then Best, D = Part, d end
		end
		local PL = Instance.new("PointLight")
		PL.Range, PL.Brightness, PL.Shadows = L[4], L[5], L[6]
		PL.Color = Color3.new(L[7], L[8], L[9])
		PL.Parent = Best
	end
	Model.WorldPivot = Base
	Model.Parent = Group
	Made += 1
	if I % 25 == 0 then task.wait() end
end
return string.format("chunk %s: %d models, %d parts", CHUNK, Made, Parts)
